//! Replays `tests/fixtures/stats_trace.tsv`, generated by running the original Go implementation
//! (`providerStats` in `android/engine/resolver_stats.go`) over a scripted sequence of operations.
//!
//! Every row asserts the whole state plus the four derived values at that row's `now`, so an
//! accidentally different truncation, clamp, weight or decay shows up immediately.

use std::path::PathBuf;

use diting_resolver_core::ProviderStats;

fn fixture_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/stats_trace.tsv")
}

const COLUMNS: usize = 19;

fn number(fields: &[&str], column: usize) -> i64 {
    fields[column]
        .parse()
        .unwrap_or_else(|error| panic!("column {column} is not a number: {error}"))
}

#[test]
fn replay_matches_the_go_trace() {
    let text = std::fs::read_to_string(fixture_path()).expect("fixture is committed");
    let mut stats = ProviderStats::new();
    let mut instance = String::new();
    let mut rows = 0;

    for (line_number, line) in text.lines().enumerate() {
        if line_number == 0 {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        assert_eq!(
            fields.len(),
            COLUMNS,
            "row {line_number} has the wrong width"
        );

        let row_instance = fields[1];
        if row_instance != instance {
            stats = ProviderStats::new();
            instance = row_instance.to_string();
        }

        let op = fields[2];
        let now = number(&fields, 3);
        let argument = number(&fields, 4);
        let decided = match op {
            "success" => {
                stats.record_success(argument, now);
                None
            }
            "failure" => {
                stats.record_failure(now);
                None
            }
            "policy_failure" => {
                stats.record_policy_failure(now);
                None
            }
            "censored" => {
                stats.record_censored(argument);
                None
            }
            "allow" => Some(stats.allow_attempt(now)),
            "score" | "snapshot" => None,
            other => panic!("row {line_number}: unknown op {other}"),
        };

        let snapshot = stats.snapshot();
        let label = |field: &str| format!("{instance}/{op} row {line_number} {field}");

        assert_eq!(
            snapshot.sample_count,
            number(&fields, 5),
            "{}",
            label("sample_count")
        );
        assert_eq!(
            snapshot.failure_count as i64,
            number(&fields, 6),
            "{}",
            label("failure_count")
        );
        assert_eq!(
            snapshot.ewma_rtt_ns,
            number(&fields, 7),
            "{}",
            label("ewma_ns")
        );
        assert_eq!(
            snapshot.rtt_var_ns,
            number(&fields, 8),
            "{}",
            label("rtt_var_ns")
        );
        let expected_bits = u64::from_str_radix(fields[9], 16).expect("fail_rate_bits is hex");
        assert_eq!(
            snapshot.fail_rate.to_bits(),
            expected_bits,
            "{}",
            label("fail_rate_bits")
        );
        assert_eq!(
            snapshot.last_failure_ns,
            number(&fields, 10),
            "{}",
            label("last_failure_ns")
        );
        assert_eq!(
            snapshot.last_success_ns,
            number(&fields, 11),
            "{}",
            label("last_success_ns")
        );
        assert_eq!(
            snapshot.circuit_open_until_ns,
            number(&fields, 12),
            "{}",
            label("circuit_until_ns")
        );
        assert_eq!(
            snapshot.probe_in_flight,
            fields[13] == "1",
            "{}",
            label("probe_in_flight")
        );
        assert_eq!(
            stats.score(now),
            number(&fields, 14),
            "{}",
            label("score_ns")
        );
        assert_eq!(
            stats.hedge_delay(),
            number(&fields, 15),
            "{}",
            label("hedge_ns")
        );
        assert_eq!(
            stats.attempt_timeout(),
            number(&fields, 16),
            "{}",
            label("attempt_ns")
        );
        assert_eq!(
            stats.udp_retry_delay(),
            number(&fields, 17),
            "{}",
            label("udp_ns")
        );

        match decided {
            Some(answer) => assert_eq!(answer, fields[18] == "1", "{}", label("allow")),
            None => assert_eq!(fields[18], "-", "{}", label("allow")),
        }
        rows += 1;
    }

    assert_eq!(rows, 76, "the fixture has one row per scripted operation");
}
